ALTER TABLE "users" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "user_scoped_read" ON "users" AS PERMISSIVE FOR SELECT TO public USING ("users"."id"=NULLIF(current_setting('rove.actor_id',true),'')::uuid OR "users"."id"=NULLIF(current_setting('rove.user_read',true),'')::uuid OR COALESCE(NULLIF(current_setting('rove.user_audience',true),'')::jsonb,'[]'::jsonb) ? "users"."id"::text OR "users"."subject"=NULLIF(current_setting('rove.identity_subject',true),'') OR ("users"."role"='driver' AND current_setting('rove.offer_matching',true)='true' AND NULLIF(current_setting('rove.offer_ride',true),'') IS NOT NULL));--> statement-breakpoint
CREATE POLICY "user_scoped_lock" ON "users" AS PERMISSIVE FOR UPDATE TO public USING (("users"."id"=NULLIF(current_setting('rove.actor_id',true),'')::uuid OR "users"."id"=NULLIF(current_setting('rove.user_read',true),'')::uuid OR COALESCE(NULLIF(current_setting('rove.user_audience',true),'')::jsonb,'[]'::jsonb) ? "users"."id"::text OR "users"."subject"=NULLIF(current_setting('rove.identity_subject',true),'') OR ("users"."role"='driver' AND current_setting('rove.offer_matching',true)='true' AND NULLIF(current_setting('rove.offer_ride',true),'') IS NOT NULL)) AND NULLIF(current_setting('rove.user_profile_write',true),'')::jsonb IS NULL AND NULLIF(current_setting('rove.user_close_write',true),'')::jsonb IS NULL) WITH CHECK (false);--> statement-breakpoint
CREATE POLICY "user_signup" ON "users" AS PERMISSIVE FOR INSERT TO public WITH CHECK ("users"."subject"=NULLIF(current_setting('rove.identity_subject',true),'') AND "users"."name"=NULLIF(current_setting('rove.identity_signup',true),'')::jsonb->>'name' AND "users"."role"=NULLIF(current_setting('rove.identity_signup',true),'')::jsonb->>'role' AND "users"."role" IN ('rider','driver') AND "users"."disabled"=false);--> statement-breakpoint
CREATE POLICY "user_profile_name" ON "users" AS PERMISSIVE FOR UPDATE TO public USING ((to_jsonb(users)-'name')=(NULLIF(current_setting('rove.user_profile_write',true),'')::jsonb-'name') AND "users"."disabled"=false) WITH CHECK (to_jsonb(users)=NULLIF(current_setting('rove.user_profile_write',true),'')::jsonb);--> statement-breakpoint
CREATE POLICY "user_account_close" ON "users" AS PERMISSIVE FOR UPDATE TO public USING ((to_jsonb(users)-'disabled')=(NULLIF(current_setting('rove.user_close_write',true),'')::jsonb-'disabled') AND current_setting('rove.actor_role',true)='staff' AND current_setting('rove.actor_mfa',true)='true') WITH CHECK (to_jsonb(users)=NULLIF(current_setting('rove.user_close_write',true),'')::jsonb AND "users"."disabled"=true);
--> statement-breakpoint
ALTER TABLE users FORCE ROW LEVEL SECURITY;
